1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="description" content="An accessible, animated pulsing circle with adjustable speed and pause controls.">
7	  <meta name="color-scheme" content="dark">
8	  <meta name="theme-color" content="#0d0d17">
9	  <title>Pulsing Circle</title>
10	  <link rel="icon" href="data:,">
11	
12	  <style>
13	    :root {
14	      --circle-hue: #8ec5ff;
15	      --circle-core: #4a7dd9;
16	      --circle-shadow: #1f3a75;
17	      --cycle: 2.5s;
18	    }
19	    * {
20	      margin: 0;
21	      padding: 0;
22	      box-sizing: border-box;
23	    }
24	    body {
25	      width: 100vw;
26	      height: 100vh;
27	      height: 100dvh;
28	      display: flex;
29	      flex-direction: column;
30	      justify-content: center;
31	      align-items: center;
32	      gap: 24px;
33	      background: radial-gradient(circle at center, #1a1a2e 0%, #0d0d17 100%);
34	      overflow: hidden;
35	    }
36	    svg {
37	      width: min(400px, 80vmin);
38	      height: min(400px, 80vmin);
39	      overflow: visible;
40	      cursor: pointer;
41	      user-select: none;
42	      -webkit-tap-highlight-color: transparent;
43	      transition: filter 0.3s ease;
44	    }
45	    .circle-btn:hover svg {
46	      filter: brightness(1.08);
47	    }
48	    .ambient {
49	      fill: var(--circle-hue);
50	      opacity: 0.12;
51	      filter: blur(30px);
52	      animation: breathe var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
53	      transform-origin: 200px 200px;
54	      will-change: transform, opacity;
55	    }
56	    .core {
57	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
58	      transform-origin: 200px 200px;
59	      filter: url(#glow);
60	      will-change: transform, opacity;
61	    }
62	    .highlight {
63	      fill: url(#highlightGradient);
64	      transform-origin: 200px 200px;
65	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
66	      pointer-events: none;
67	      will-change: transform, opacity;
68	    }
69	    .ring {
70	      fill: none;
71	      stroke: var(--circle-hue);
72	      stroke-width: 2.5;
73	      transform-origin: 200px 200px;
74	      animation: ripple var(--cycle) cubic-bezier(0.2, 0.6, 0.4, 1) infinite;
75	      will-change: transform, opacity, stroke-width;
76	    }
77	    .ring--delay-1 {
78	      animation-delay: calc(var(--cycle) / 3);
79	    }
80	    .ring--delay-2 {
81	      animation-delay: calc(var(--cycle) / 3 * 2);
82	    }
83	    @keyframes pulse {
84	      0%, 100% {
85	        transform: scale(1);
86	        opacity: 0.9;
87	      }
88	      50% {
89	        transform: scale(1.05);
90	        opacity: 1;
91	      }
92	    }
93	    @keyframes breathe {
94	      0%, 100% {
95	        transform: scale(0.95);
96	        opacity: 0.1;
97	      }
98	      50% {
99	        transform: scale(1.1);
100	        opacity: 0.18;
101	      }
102	    }
103	    @keyframes ripple {
104	      0% {
105	        transform: scale(1);
106	        opacity: 0.6;
107	        stroke-width: 2.5;
108	      }
109	      100% {
110	        transform: scale(1.35);
111	        opacity: 0;
112	        stroke-width: 0.5;
113	      }
114	    }
115	    body.paused .core,
116	    body.paused .ring,
117	    body.paused .ambient,
118	    body.paused .highlight {
119	      animation-play-state: paused;
120	    }
121	    /* Force-paused until JS takes over (below), avoiding a flash of motion;
122	       once JS is ready, control defers entirely to body.paused so the user
123	       can still explicitly resume even with reduced motion preferred. */
124	    @media (prefers-reduced-motion: reduce) {
125	      body:not(.js-ready) .core,
126	      body:not(.js-ready) .ring,
127	      body:not(.js-ready) .ambient,
128	      body:not(.js-ready) .highlight {
129	        animation-play-state: paused;
130	      }
131	    }
132	    .speed-label {
133	      color: var(--circle-hue);
134	      font-family: system-ui, sans-serif;
135	      font-size: 0.85rem;
136	      letter-spacing: 0.05em;
137	      opacity: 0.85;
138	      user-select: none;
139	      text-align: center;
140	    }
141	    .hint {
142	      display: block;
143	      margin-top: 4px;
144	      font-size: 0.7rem;
145	      opacity: 1;
146	    }
147	    .controls {
148	      display: flex;
149	      align-items: center;
150	      gap: 12px;
151	      max-width: min(320px, 90vw);
152	    }
153	    .pause-btn {
154	      display: inline-flex;
155	      align-items: center;
156	      justify-content: center;
157	      width: 44px;
158	      height: 44px;
159	      padding: 0;
160	      border-radius: 50%;
161	      border: 1px solid var(--circle-hue);
162	      background: transparent;
163	      color: var(--circle-hue);
164	      cursor: pointer;
165	      touch-action: manipulation;
166	      transition: background 0.2s ease;
167	    }
168	    .pause-btn:hover {
169	      background: rgba(142, 197, 255, 0.15);
170	    }
171	    .pause-btn:focus-visible {
172	      outline: 2px solid var(--circle-hue);
173	      outline-offset: 2px;
174	    }
175	    @media (prefers-contrast: more) {
176	      .pause-btn {
177	        border-width: 2px;
178	      }
179	      .ring {
180	        stroke-width: 3.5;
181	      }
182	    }
183	    .pause-btn svg {
184	      width: 14px;
185	      height: 14px;
186	    }
187	    .circle-btn {
188	      display: inline-flex;
189	      padding: 0;
190	      border: none;
191	      background: none;
192	      cursor: pointer;
193	      touch-action: manipulation;
194	      -webkit-tap-highlight-color: transparent;
195	      border-radius: 50%;
196	    }
197	    .circle-btn:focus-visible {
198	      outline: none;
199	    }
200	    .circle-btn:focus-visible svg {
201	      outline: 2px solid var(--circle-hue);
202	      outline-offset: 8px;
203	      border-radius: 50%;
204	    }
205	    .no-js .controls {
206	      display: none;
207	    }
208	    .no-js .circle-btn {
209	      cursor: default;
210	    }
211	    .visually-hidden {
212	      position: absolute;
213	      width: 1px;
214	      height: 1px;
215	      padding: 0;
216	      margin: -1px;
217	      overflow: hidden;
218	      clip: rect(0, 0, 0, 0);
219	      white-space: nowrap;
220	      border: 0;
221	    }
222	    .noscript-note {
223	      color: var(--circle-hue);
224	      font-family: system-ui, sans-serif;
225	      font-size: 0.8rem;
226	      opacity: 0.75;
227	      text-align: center;
228	      max-width: min(320px, 90vw);
229	    }
230	  </style>
231	</head>
232	<body class="no-js">
233	  <h1 class="visually-hidden">Pulsing Circle</h1>
234	  <button type="button" class="circle-btn" id="circleBtn" aria-label="Pulsing blue circle animation" aria-describedby="speedText" title="Pulsing blue circle animation">
235	  <svg viewBox="0 0 400 400" focusable="false" aria-hidden="true">
236	    <defs>
237	      <radialGradient id="circleGradient" cx="35%" cy="35%" r="65%">
238	        <stop offset="0%" style="stop-color: var(--circle-hue)"/>
239	        <stop offset="55%" style="stop-color: var(--circle-core)"/>
240	        <stop offset="100%" style="stop-color: var(--circle-shadow)"/>
241	      </radialGradient>
242	      <radialGradient id="highlightGradient" cx="32%" cy="28%" r="22%">
243	        <stop offset="0%" stop-color="#ffffff" stop-opacity="0.55"/>
244	        <stop offset="100%" stop-color="#ffffff" stop-opacity="0"/>
245	      </radialGradient>
246	      <filter id="glow" x="-80%" y="-80%" width="260%" height="260%">
247	        <feGaussianBlur in="SourceGraphic" stdDeviation="10" result="blur"/>
248	        <feColorMatrix in="blur" type="matrix"
249	          values="0 0 0 0 0.55  0 0 0 0 0.77  0 0 0 0 1  0 0 0 0.9 0" result="tintedBlur"/>
250	        <feMerge>
251	          <feMergeNode in="tintedBlur"/>
252	          <feMergeNode in="SourceGraphic"/>
253	        </feMerge>
254	      </filter>
255	    </defs>
256	    <circle class="ambient" cx="200" cy="200" r="160"/>
257	    <circle class="ring" cx="200" cy="200" r="140"/>
258	    <circle class="ring ring--delay-1" cx="200" cy="200" r="140"/>
259	    <circle class="ring ring--delay-2" cx="200" cy="200" r="140"/>
260	    <circle class="core" cx="200" cy="200" r="140" fill="url(#circleGradient)"/>
261	    <circle class="highlight" cx="200" cy="200" r="140"/>
262	  </svg>
263	  </button>
264	  <div class="controls">
265	    <button type="button" class="pause-btn" id="pauseBtn" aria-pressed="false" aria-label="Pause animation" title="Pause animation">
266	      <svg id="pauseIcon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
267	        <path d="M6 4h4v16H6zM14 4h4v16h-4z"/>
268	      </svg>
269	    </button>
270	    <p class="speed-label" id="speedLabel">
271	      <span id="speedText" aria-live="polite">Normal speed</span>
272	      <span class="hint" aria-hidden="true">Activate circle to change speed</span>
273	    </p>
274	  </div>
275	  <noscript>
276	    <p class="noscript-note">Enable JavaScript to change the animation speed or pause it.</p>
277	  </noscript>
278	  <script>
279	    const circleBtn = document.getElementById('circleBtn');
280	    const speedText = document.getElementById('speedText');
281	    const pauseBtn = document.getElementById('pauseBtn');
282	    const pauseIcon = document.getElementById('pauseIcon');
283	    const animatedEls = document.querySelectorAll('.core, .ring, .ambient, .highlight');
284	    const PLAY_ICON = '<path d="M8 5l11 7-11 7z"/>';
285	    const PAUSE_ICON = '<path d="M6 4h4v16H6zM14 4h4v16h-4z"/>';
286	    const speeds = [
287	      { value: '2.5s', name: 'Normal speed' },
288	      { value: '1.2s', name: 'Fast speed' },
289	      { value: '4.5s', name: 'Slow speed' },
290	    ];
291	    const reducedMotionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
292	    let speedIndex = 0;
293	    let manuallyPaused = reducedMotionQuery.matches;
294	    // Once the user has explicitly toggled pause/play, respect that choice
295	    // instead of letting a later OS-level reduced-motion change override it.
296	    let userHasChosen = false;
297	
298	    const STORAGE_KEY = 'pulsing-circle-prefs';
299	    try {
300	      const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
301	      if (saved && Number.isInteger(saved.speedIndex) && speeds[saved.speedIndex]) {
302	        speedIndex = saved.speedIndex;
303	        circleBtn.style.setProperty('--cycle', speeds[speedIndex].value);
304	      }
305	      if (saved && typeof saved.manuallyPaused === 'boolean') {
306	        manuallyPaused = saved.manuallyPaused;
307	        userHasChosen = true;
308	      }
309	    } catch {
310	      // Ignore malformed or inaccessible storage; fall back to defaults.
311	    }
312	
313	    function savePrefs() {
314	      try {
315	        localStorage.setItem(STORAGE_KEY, JSON.stringify({ speedIndex, manuallyPaused }));
316	      } catch {
317	        // Storage may be unavailable (e.g. private browsing); ignore.
318	      }
319	    }
320	
321	    function updateLabels() {
322	      const { name } = speeds[speedIndex];
323	      speedText.textContent = manuallyPaused ? `${name} (paused)` : name;
324	      circleBtn.title = `Activate to change pulse speed (currently ${name})`;
325	    }
326	
327	    function cycleSpeed() {
328	      speedIndex = (speedIndex + 1) % speeds.length;
329	      const { value } = speeds[speedIndex];
330	      circleBtn.style.setProperty('--cycle', value);
331	      restartAnimations();
332	      updateLabels();
333	      savePrefs();
334	    }
335	
336	    // Restart animations from the beginning so a new speed feels immediate
337	    // instead of jumping mid-cycle.
338	    function restartAnimations() {
339	      animatedEls.forEach((el) => {
340	        el.style.animation = 'none';
341	      });
342	      void circleBtn.offsetWidth;
343	      animatedEls.forEach((el) => {
344	        el.style.animation = '';
345	      });
346	    }
347	
348	    function applyPauseState() {
349	      document.body.classList.toggle('paused', document.hidden || manuallyPaused);
350	      pauseBtn.setAttribute('aria-pressed', String(manuallyPaused));
351	      pauseBtn.setAttribute('aria-label', manuallyPaused ? 'Resume animation' : 'Pause animation');
352	      pauseBtn.setAttribute('title', manuallyPaused ? 'Resume animation' : 'Pause animation');
353	      pauseIcon.innerHTML = manuallyPaused ? PLAY_ICON : PAUSE_ICON;
354	      updateLabels();
355	    }
356	
357	    function togglePause() {
358	      manuallyPaused = !manuallyPaused;
359	      userHasChosen = true;
360	      applyPauseState();
361	      savePrefs();
362	    }
363	
364	    circleBtn.addEventListener('click', cycleSpeed);
365	    pauseBtn.addEventListener('click', togglePause);
366	
367	    document.addEventListener('visibilitychange', applyPauseState);
368	
369	    const onReducedMotionChange = (e) => {
370	      if (userHasChosen) return;
371	      manuallyPaused = e.matches;
372	      applyPauseState();
373	    };
374	    if (reducedMotionQuery.addEventListener) {
375	      reducedMotionQuery.addEventListener('change', onReducedMotionChange);
376	    } else if (reducedMotionQuery.addListener) {
377	      // Safari < 14 fallback.
378	      reducedMotionQuery.addListener(onReducedMotionChange);
379	    }
380	
381	    // Keep multiple open tabs/windows of this page in sync with each other.
382	    window.addEventListener('storage', (e) => {
383	      if (e.key !== STORAGE_KEY || !e.newValue) return;
384	      try {
385	        const saved = JSON.parse(e.newValue);
386	        if (Number.isInteger(saved.speedIndex) && speeds[saved.speedIndex] && saved.speedIndex !== speedIndex) {
387	          speedIndex = saved.speedIndex;
388	          circleBtn.style.setProperty('--cycle', speeds[speedIndex].value);
389	          restartAnimations();
390	        }
391	        if (typeof saved.manuallyPaused === 'boolean') {
392	          manuallyPaused = saved.manuallyPaused;
393	          userHasChosen = true;
394	        }
395	        applyPauseState();
396	        updateLabels();
397	      } catch {
398	        // Ignore malformed storage updates from other tabs.
399	      }
400	    });
401	
402	    applyPauseState();
403	    updateLabels();
404	    circleBtn.setAttribute('aria-label', 'Pulsing blue circle animation. Activate to change pulse speed.');
405	    document.body.classList.add('js-ready');
406	    document.body.classList.remove('no-js');
407	  </script>
408	</body>
409	</html>
